package app.pocketagent.ai

import kotlinx.serialization.Serializable
import kotlinx.serialization.builtins.ListSerializer

/**
 * Public MCP servers the app knows about, so work that needs them does not start from an empty list. They need no
 * account and no token. Two are listed from the first start; the others are offered as suggestions. Any of them
 * can be removed, and added again, like a server the person typed in themselves.
 *
 * Their lists of tools are kept here, as they were when this version was made, so that listing a server costs
 * nothing: no server is contacted until the person approves a call to it, or asks for it to be connected.
 * And because not everybody needs them, their tools travel with a request only when the person names the server
 * with @mcp or what was asked matches what a tool does (see [ToolPicker]).
 *
 * These are other people's services. My PAI is not affiliated with any of them; their names belong to their owners.
 */
object McpPresets {
    @Serializable
    class Preset(val id: String, val name: String, val url: String, val about: String, val byDefault: Boolean = false, val tools: List<McpTool> = emptyList())

    /** Raised when the default set changes, so a new default reaches people who already have the app, once. */
    const val VERSION = 1

    val ALL: List<Preset> by lazy { AppJson.decodeFromString(ListSerializer(Preset.serializer()), RAW) }

    fun isPreset(id: String) = id.startsWith("preset-")

    /** The server as it is listed before anybody has contacted it. */
    fun server(p: Preset): McpServer = McpServer(id = p.id, name = p.name, url = p.url, on = true, tools = p.tools, checkedAt = 0, changedAt = 1)

    /** What to add on the first start of a version that brought new defaults: the default ones not there yet and not removed by the person. */
    fun missing(have: List<McpServer>, gone: Map<String, Long>): List<McpServer> =
        ALL.filter { p -> p.byDefault && p.id !in gone && have.none { it.id == p.id || it.url.trimEnd('/') == p.url.trimEnd('/') } }.map(::server)

    private const val RAW = """[{"id":"preset-deepwiki","name":"DeepWiki","url":"https://mcp.deepwiki.com/mcp","about":"Ask about any public GitHub repository: how it works and where things are.","byDefault":true,"tools":[{"name":"ask_wiki_question","description":"Ask any question about a GitHub repository's codebase and get an AI-powered answer grounded in its DeepWiki.","schema":"{\"type\":\"object\",\"additionalProperties\":false,\"properties\":{\"repoName\":{\"anyOf\":[{\"type\":\"string\"},{\"items\":{\"type\":\"string\"},\"type\":\"array\"}],\"description\":\"GitHub repository or list of repositories (max 10) in owner/repo format.\"},\"question\":{\"description\":\"The question to ask about the repository.\",\"type\":\"string\"}},\"required\":[\"repoName\",\"question\"]}"},{"name":"read_wiki_contents","description":"View documentation about a GitHub repository.","schema":"{\"type\":\"object\",\"additionalProperties\":false,\"properties\":{\"repoName\":{\"description\":\"GitHub repository in owner/repo format (e.g. \\\"facebook/react\\\").\",\"type\":\"string\"}},\"required\":[\"repoName\"]}"},{"name":"read_wiki_structure","description":"Get a list of documentation topics for a GitHub repository.","schema":"{\"type\":\"object\",\"additionalProperties\":false,\"properties\":{\"repoName\":{\"description\":\"GitHub repository in owner/repo format (e.g. \\\"facebook/react\\\").\",\"type\":\"string\"}},\"required\":[\"repoName\"]}"}]},{"id":"preset-context7","name":"Context7","url":"https://mcp.context7.com/mcp","about":"Current documentation and examples for software libraries.","byDefault":true,"tools":[{"name":"resolve-library-id","description":"Resolves a package/product name to a Context7-compatible library ID and returns matching libraries. You MUST call this function before 'Query Documentation' tool to obtain a valid Context7-compatible library ID UNLESS the user explicitly provides a library ID in the format '/org/project' or '/org/project/version' in their query. Each result includes: - Library ID: Context7-compatible identifier (format: /org/project) - Name: Library or package name - Description: Short summary - Code Snippets: Number of available code examples - Source Reputation: Authority indicator (High, Medium, Low, or Unknown) - Benchmark Score: Quality indicator (100 is the highest score) - Versions: List of versions i","schema":"{\"type\":\"object\",\"${'$'}schema\":\"https://json-schema.org/draft/2020-12/schema\",\"properties\":{\"query\":{\"type\":\"string\",\"description\":\"What to look up in the library's documentation. This is used to rank library results by relevance to what the user is trying to accomplish. The query is sent to the Context7 API for processing. Do not include any sensitive or confidential information such as API keys, passwords, credentials, personal data, or proprietary code in your query.\"},\"libraryName\":{\"type\":\"string\",\"description\":\"Library name to search for and retrieve a Context7-compatible library ID. Use the official library name with proper punctuation \\u2014 e.g., 'Next.js' instead of 'nextjs', 'Customer.io' instead of 'customerio', 'Three.js' instead of 'threejs'.\"}},\"required\":[\"query\",\"libraryName\"]}"},{"name":"query-docs","description":"Retrieves and queries up-to-date documentation and code examples from Context7 for any programming library or framework. You must call 'Resolve Context7 Library ID' tool first to obtain the exact Context7-compatible library ID required to use this tool, UNLESS the user explicitly provides a library ID in the format '/org/project' or '/org/project/version' in their query. Do not call this tool more than 3 times per question. If you know the programming language the user is working in, pass it as `language` so the results match their setup.","schema":"{\"type\":\"object\",\"${'$'}schema\":\"https://json-schema.org/draft/2020-12/schema\",\"properties\":{\"libraryId\":{\"type\":\"string\",\"description\":\"Exact Context7-compatible library ID (e.g., '/mongodb/docs', '/vercel/next.js', '/supabase/supabase', '/vercel/next.js/v16.2.9') retrieved from 'resolve-library-id' or directly from user query in the format '/org/project' or '/org/project/version'.\"},\"query\":{\"type\":\"string\",\"description\":\"What to look up in the library's documentation, scoped to a single concept. Be specific and include relevant details, but keep each query to one topic \\u2014 if the user's question spans multiple distinct concepts, make a separate call per concept instead of combining them, unless the question is about how the concepts interact. Good: 'How to set up authentication with JWT in Express.js' or 'React useEffect cleanup function examples'. Bad (too vague): 'auth' or 'hooks'. Bad (too broad): 'routing and auth and caching in Next.js'. The query is sent to the Context7 API for processing. Do not include any sensitive or confidential information such as API keys, passwords, credentials, personal data, or proprietary code in your query.\"},\"language\":{\"description\":\"Programming language the user is writing code in, such as 'Python', 'TypeScript', 'Go', or 'C#'. Ranks code examples in that language first. Leave it out when the language is unknown or does not apply.\",\"type\":\"string\"}},\"required\":[\"libraryId\",\"query\"]}"}]},{"id":"preset-mslearn","name":"Microsoft Learn","url":"https://learn.microsoft.com/api/mcp","about":"Search and read the official Microsoft and Azure documentation.","byDefault":false,"tools":[{"name":"microsoft_docs_search","description":"Search official Microsoft/Azure documentation to find the most relevant and trustworthy content for a user's query. This tool returns up to 10 high-quality content chunks (each max 500 tokens), extracted from Microsoft Learn and other official sources. Each result includes the article title, URL, and a self-contained content excerpt optimized for fast retrieval and reasoning. Always use this tool to quickly ground your answers in accurate, first-party Microsoft/Azure knowledge. ## Follow-up Pattern To ensure completeness, use microsoft_docs_fetch when high-value pages are identified by search. The fetch tool complements search by providing the full detail. This is a required step for compreh","schema":"{\"type\":\"object\",\"properties\":{\"query\":{\"description\":\"a query or topic about Microsoft/Azure products, services, platforms, developer tools, frameworks, or APIs\",\"type\":\"string\",\"default\":null}}}"},{"name":"microsoft_code_sample_search","description":"Search for code snippets and examples in official Microsoft Learn documentation. This tool retrieves relevant code samples from Microsoft documentation pages providing developers with practical implementation examples and best practices for Microsoft/Azure products and services related coding tasks. This tool will help you use the **LATEST OFFICIAL** code snippets to empower coding capabilities. ## When to Use This Tool - When you are going to provide sample Microsoft/Azure related code snippets in your answers. - When you are **generating any Microsoft/Azure related code**. ## Usage Pattern Input a descriptive query, or SDK/class/method name to retrieve related code samples. The optional pa","schema":"{\"type\":\"object\",\"properties\":{\"query\":{\"description\":\"a descriptive query, SDK name, method name or code snippet related to Microsoft/Azure products, services, platforms, developer tools, frameworks, APIs or SDKs\",\"type\":\"string\"},\"language\":{\"description\":\"Optional parameter specifying the programming language of code snippets to retrieve. Can significantly improve search quality if provided. Eligible values: csharp javascript typescript python powershell azurecli al sql java kusto cpp go rust ruby php\",\"type\":\"string\",\"default\":null}},\"required\":[\"query\"]}"},{"name":"microsoft_docs_fetch","description":"Fetch and convert a Microsoft Learn documentation webpage to markdown format. This tool retrieves the latest complete content of Microsoft documentation webpages including Azure, .NET, Microsoft 365, and other Microsoft technologies. ## When to Use This Tool - When search results provide incomplete information or truncated content - When you need complete step-by-step procedures or tutorials - When you need troubleshooting sections, prerequisites, or detailed explanations - When search results reference a specific page that seems highly relevant - For comprehensive guides that require full context ## Usage Pattern Use this tool AFTER microsoft_docs_search when you identify specific high-valu","schema":"{\"type\":\"object\",\"properties\":{\"url\":{\"description\":\"URL of the Microsoft documentation page to read\",\"type\":\"string\"}},\"required\":[\"url\"]}"}]},{"id":"preset-cloudflare","name":"Cloudflare Docs","url":"https://docs.mcp.cloudflare.com/mcp","about":"Search the Cloudflare documentation.","byDefault":false,"tools":[{"name":"search_cloudflare_documentation","description":"Search the Cloudflare documentation. This tool should be used to answer any question about Cloudflare products or features, including: - Workers, Pages, R2, Images, Stream, D1, Durable Objects, KV, Workflows, Hyperdrive, Queues - AI Search, Workers AI, Vectorize, AI Gateway, Browser Run - Zero Trust, Access, Tunnel, Gateway, Browser Isolation, WARP, DDOS, Magic Transit, Magic WAN - CDN, Cache, DNS, Zaraz, Argo, Rulesets, Terraform, Account and Billing Results are returned as semantically similar chunks to the query.","schema":"{\"type\":\"object\",\"${'$'}schema\":\"https://json-schema.org/draft/2020-12/schema\",\"properties\":{\"query\":{\"type\":\"string\"}},\"required\":[\"query\"]}"},{"name":"migrate_pages_to_workers_guide","description":"ALWAYS read this guide before migrating Pages projects to Workers.","schema":"{\"type\":\"object\",\"${'$'}schema\":\"https://json-schema.org/draft/2020-12/schema\",\"properties\":{}}"}]}]"""
}
